function e(e){if(!e.length)return{sampleSize:0,brierScore:0,logLoss:0,calibrationError:0};let t=0,n=0,r=new Map;for(let i of e){let e=Math.max(.001,Math.min(.999,i.predicted));t+=(e-i.outcome)**2,n+=-(i.outcome*Math.log(e)+(1-i.outcome)*Math.log(1-e));let a=Math.min(9,Math.floor(e*10)),o=r.get(a)||{n:0,sumPred:0,sumOutcome:0};o.n++,o.sumPred+=e,o.sumOutcome+=i.outcome,r.set(a,o)}let i=0;for(let t of r.values())i+=t.n/e.length*Math.abs(t.sumPred/t.n-t.sumOutcome/t.n);return{sampleSize:e.length,brierScore:t/e.length,logLoss:n/e.length,calibrationError:i}}export{e as t};